{"filename":"routes.py","content":"from flask import Blueprint, request, jsonify, current_app
from models import get_db

bp = Blueprint('api', __name__)


def task_to_dict(row):
    """Convert a SQLite row tuple to a dict with proper keys."""
    return {
        'id': row['id'],
        'title': row['title'],
        'due_date': row['due_date'],
        'priority': row['priority'],
        'completed': bool(row['completed'])
    }

@bp.route('/tasks', methods=['GET'])
def get_tasks():
    db = get_db()
    cursor = db.execute('SELECT id, title, due_date, priority, completed FROM task')
    rows = cursor.fetchall()
    tasks = [task_to_dict(row) for row in rows]
    return jsonify({'success': True, 'data': tasks}), 200

@bp.route('/tasks', methods=['POST'])
def create_task():
    data = request.get_json() or {}
    title = data.get('title')
    due_date = data.get('due_date')
    priority = data.get('priority')
    completed = data.get('completed', False)

    db = get_db()
    cursor = db.execute(
        'INSERT INTO task (title, due_date, priority, completed) VALUES (?, ?, ?, ?)',
        (title, due_date, priority, int(completed))
    )
    db.commit()
    task_id = cursor.lastrowid
    return jsonify({'success': True, 'data': {'id': task_id}}), 201

@bp.route('/tasks/<int:item_id>', methods=['PATCH'])
def update_task(item_id):
    data = request.get_json() or {}
    fields = []
    values = []
    if 'title' in data:
        fields.append('title = ?')
        values.append(data['title'])
    if 'due_date' in data:
        fields.append('due_date = ?')
        values.append(data['due_date'])
    if 'priority' in data:
        fields.append('priority = ?')
        values.append(data['priority'])
    if 'completed' in data:
        fields.append('completed = ?')
        values.append(int(data['completed']))
    if not fields:
        return jsonify({'success': False, 'error': 'No fields to update'}), 400

    values.append(item_id)
    db = get_db()
    db.execute(f"UPDATE task SET {', '.join(fields)} WHERE id = ?", values)
    db.commit()
    return jsonify({'success': True, 'data': {'id': item_id}}), 200

@bp.route('/tasks/<int:item_id>', methods=['DELETE'])
def delete_task(item_id):
    db = get_db()
    db.execute('DELETE FROM task WHERE id = ?', (item_id,))
    db.commit()
    return jsonify({'success': True, 'data': {'id': item_id}}), 200

@bp.route('/tasks/<int:item_id>', methods=['GET'])
def get_task(item_id):
    db = get_db()
    cursor = db.execute('SELECT id, title, due_date, priority, completed FROM task WHERE id = ?', (item_id,))
    row = cursor.fetchone()
    if row is None:
        return jsonify({'success': False, 'error': 'Task not found'}), 404
    task = task_to_dict(row)
    return jsonify({'success': True, 'data': task}), 200
